print(
    r"""
We consider hermitean matrices

    / a   b \
M = |       |
    \ c   d /

and create the instruction set for a specific routine, that 
performs the 2x2 matrix commutation and multiplies with a
factor of i
"""
)

from phoenix.keymap import KeyMap
from phoenix.fgen.instruction import BiLinearOperationInstruction
from phoenix.fgen.instructionvar import InstructionVariable

km_2x2_herm_matrix = KeyMap(name="2x2 hermitean matrix")

# we use the pauli matrices as generators of the set of 2x2 hermitean matrices
# and represent any matrix by their coefficients.
# We keep the application as a time evolution in quantum mechanics in our head.
# Here, the identity coefficient sets the trace of the operator. Which is 1 for
# any valid state and can be set to 0 for any hamiltonian (would act as a global
# phase)
km_2x2_herm_matrix.entry("x")
km_2x2_herm_matrix.entry("y")
km_2x2_herm_matrix.entry("z")

# the description of our operation requires three variables
matrix_a = InstructionVariable.new("mat_a", config=km_2x2_herm_matrix)
matrix_b = InstructionVariable.new("mat_b", config=km_2x2_herm_matrix)
matrix_c = InstructionVariable.new("mat_c", config=km_2x2_herm_matrix)
# these three instruction variables are now classes, that you can call and
# pass an offset to them as an argument

# we now collect all instructions required
all_instructions = []

# the bilinear instruction is of the form
# y[key_tgt0] += a * x1[key_src1] * x2[key_src2]

# as we have chosen a representation as a linear combination of pauli matrices,
# let us use the algebraic commutation property and include the additional factor
# of i right away

# these are all non-vanishing commutators via (src_a, src_b): (result, phase)
pauli_comm = {
    ("x", "y"): ("z", 2j),
    ("y", "x"): ("z", -2j),
    ("y", "z"): ("x", 2j),
    ("z", "y"): ("x", -2j),
    ("z", "x"): ("y", 2j),
    ("x", "z"): ("y", -2j),
}

for (src_a, src_b), (target, phase) in pauli_comm.items():
    all_instructions.append(
        BiLinearOperationInstruction(
            tgt0=matrix_c(target),
            src0=matrix_a(src_a),  # here is how to have an instruction var
            src1=matrix_b(src_b),  # evaluated at an offset
            alpha=1j * phase,
        )
    )

print("all instructions:")
for instruction in all_instructions:
    print(
        " -> "
        + ", ".join(
            f"{key}={value}"
            for key, value in instruction.to_dict(
                "src0", "src1", "alpha", "tgt0"
            ).items()  # we request some of the dict entries
        )
    )
